class Solution {
public:
    int convertTime(string current, string correct) {
        int cur = ((current[0] - '0') * 10 + (current[1] - '0')) * 60
                + (current[3] - '0') * 10 + (current[4] - '0');
        int cor = ((correct[0] - '0') * 10 + (correct[1] - '0')) * 60
                + (correct[3] - '0') * 10 + (correct[4] - '0');
        int diff = cor - cur;
        int ops = 0;
        int denoms[4] = {60, 15, 5, 1};
        for (int i = 0; i < 4; i++) {
            ops += diff / denoms[i];
            diff %= denoms[i];
        }
        return ops;
    }
};
